import { getToolbarState, getNavigationDirection, getNextEnabledValue } from '@dreadnought/core';
const items = [{ value: 'save' }, { value: 'copy' }];
export function tabIndexes(activeValue?: string) {
  const state = getToolbarState({ items, activeValue });
  return items.map(item => ({ value: item.value, tabIndex: item.value === state.tabStopValue ? 0 : -1 }));
}
export function onKeyDown(event: KeyboardEvent, currentValue: string, buttons: ReadonlyMap<string, HTMLButtonElement>) {
  if (event.defaultPrevented || event.isComposing || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  const direction = getNavigationDirection(event.key, { orientation: 'horizontal' });
  if (!direction) return;
  const nextValue = getNextEnabledValue(items, currentValue, direction);
  event.preventDefault();
  if (nextValue) buttons.get(nextValue)?.focus();
}
